    def buddyStrings(self, A: str, B: str) -> bool:
        if len(A) != len(B): 
            return False

        if A == B:
            seen = set()
            for ch in A:
                if ch in seen:
                    return True
                seen.add(ch)
            return False

        pairs = []
        for a, b in zip(A, B):
