class Solution:
    def buddyStrings(self, A: str, B: str) -> bool:
        from collections import Counter

        if len(A) != len(B):
            return False

        # Count occurrences of each character
        count_A = Counter(A)
        count_B = Counter(B)

        # Check if counts are the same
        if count_A != count_B:
            return False

        # Find mismatched characters
        mismatched_chars = [A[i] for i in range(len(A))) if A[i] != B[i]]]

        # Check if there are exactly 2 mismatched characters
        if len(mismatched_chars)) == 2 and mismatched_chars[0] == mismatched_chars[1]:
            return True
        else:
            return False

