class Solution:
    def findNthDigit(self, n: int) -> int:
        if n < 10:
            return n
        digits = 1
        while n > digits * 9 * 10**(digits-1)):
            n -= digits * 9 * 10**(digits-1))
            digits += 1
        num = 10**(digits-1)) + (n - 1) // digits
        return int(str(num][(n - 1)) % digits])[0])

