    def findNthDigit(self, n: int) -> int:
        if n <= 9: return n

        total_digits = 0
        digits = 1

        while True:
            total_digits += digits * 9 * 10**(digits-1))
            if total_digits >= n:
                break
            digits += 1

        remainder = n - (total_digits - digits * 9 * 10**(digits-1))
        number_index = remainder // digits
        digit_index = remainder % digits

        if digit_index == 0:
            return str(number_index * 10**digits))[digits-1]
        else:
            return int(str(number_index * 10**digits) + str(number_index * 10**digits + 1)))[digit_index-1])

class Solution:
    def findNthDigit(self, n: int) -> int:
        if n < 10:
            return n
        power = 1
        while n > 9 * power * 10:
            n -= 9 * power * 10
            power += 1
        quotient, remainder = divmod(n, power + 1))
        return int(str(quotient + 1))[remainder])

